import "core-js/modules/web.dom.iterable";
import * as echarts from "echarts";
export default {
  props: ["formValue"],
  data: function data() {
    return {
      qrcode: null,
      deviceStatus: '',
      deviceType: '',
      device_type: '',
      getEchartXData: ['A 机房级别', 'B 机房功能', 'S 设备状态', 'T 超龄时间', 'C 维保情况', 'D 设备归属部门', 'E 服务风险', 'F 运行自评', 'H n-1满足情况'],
      getEchartData: [],
      score: 0,
      rank: '',
      detail: {},
      tooltipContentL: []
    };
  },
  computed: {
    getDeviceHeadImage: function getDeviceHeadImage() {
      if (this.deviceType === '安全设备') {
        return require('@/assets/taizhang/safeDevice.png');
      } else if (this.deviceType === '办公设备') {
        return require('@/assets/taizhang/bangongDevice.png');
      } else if (this.deviceType === '备品备件') {
        return require('@/assets/taizhang/beijianDevice.png');
      } else if (this.deviceType === '存储设备') {
        return require('@/assets/taizhang/cunchuDevice.png');
      } else if (this.deviceType === '辅助设备') {
        return require('@/assets/taizhang/fuzhuDevice.png');
      } else if (this.deviceType === '基础设施') {
        return require('@/assets/taizhang/jichuDevice.png');
      } else if (this.deviceType === '网络设备') {
        return require('@/assets/taizhang/wangluoDevice.png');
      } else if (this.deviceType === '终端设备') {
        return require('@/assets/taizhang/zhongduanDevice.png');
      } else if (this.deviceType === '主机设备') {
        return require('@/assets/taizhang/zhujiDevice.png');
      }
      return '';
    }
  },
  methods: {
    setData: function setData(score, data) {
      this.score = score;
      this.detail = data;
      this.tooltipContentL = [this.detail.roomLevelScore, this.detail.roomFunctionScore, this.detail.deviceStatusScore, this.detail.overAgeScore, this.detail.maintenanceScore, this.detail.deptScore, this.detail.serviceRiskScore, this.detail.appriseOwnScore, this.detail.customizeScore];
      this.getEchartData = [this.detail.roomLevelScore >= 10 ? 10 : this.detail.roomLevelScore, this.detail.roomFunctionScore >= 10 ? 10 : this.detail.roomFunctionScore, this.detail.deviceStatusScore >= 10 ? 10 : this.detail.deviceStatusScore, this.detail.overAgeScore >= 10 ? 10 : this.detail.overAgeScore, this.detail.maintenanceScore >= 10 ? 10 : this.detail.maintenanceScore, this.detail.deptScore >= 10 ? 10 : this.detail.deptScore, this.detail.serviceRiskScore >= 10 ? 10 : this.detail.serviceRiskScore, this.detail.appriseOwnScore >= 10 ? 10 : this.detail.appriseOwnScore, this.detail.customizeScore >= 10 ? 10 : this.detail.customizeScore];
      this.echartRadarInit();
    },
    setRank: function setRank(rank) {
      if (this.score == 0) {
        this.rank = '--';
      } else {
        this.rank = rank;
      }
    },
    // 雷达图
    echartRadarInit: function echartRadarInit() {
      var _this = this;
      var myChart = echarts.init(document.getElementById("radarEcharts"));
      // 指定图表的配置项和数据
      var option = {
        // grid:{
        //   left:'10%',
        //   top:'10%',
        //   right:'10%',
        //   bottom:'10%',
        //   containLabel:true,
        // },
        legend: {
          show: false
        },
        tooltip: {
          trigger: 'item',
          position: 'bottom',
          formatter: function formatter() {
            // console.log( this.getEchartXData,'------------------');
            var tooltipContent = '';
            _this.getEchartXData.forEach(function (item, index) {
              var value = _this.tooltipContentL[index];
              tooltipContent += "".concat(item, ":").concat(value, " <br>");
            });
            return tooltipContent;
          }
        },
        radar: {
          shape: "polygon",
          radius: "60%",
          center: ['50%', '50%'],
          splitNumber: 5,
          clockwise: true,
          indicator: this.getEchartXData.map(function (item) {
            return {
              name: item,
              max: 10
            };
          }),
          nameGap: 10,
          name: {
            textStyle: {
              color: "#333",
              fontSize: 10
            }
          },
          splitLine: {
            lineStyle: {
              color: '#606266',
              width: 0.2
            }
          },
          axisLine: {
            show: false
          },
          splitArea: {
            show: false
          }
        },
        series: [{
          type: "radar",
          data: [{
            value: this.getEchartData,
            name: '设备配置表'
          }],
          itemStyle: {
            color: {
              type: "linear",
              x: 0,
              y: 0,
              x2: 0,
              y2: 1,
              colorStops: [{
                offset: 0,
                color: "#1673FF" // 0% 处的颜色
              }, {
                offset: 1,
                color: "#1673FF" // 100% 处的颜色
              }],
              global: false // 缺省为 false
            }
          },
          lineStyle: {
            width: 1,
            color: "#1673FF"
          }
        }]
      };

      // 使用刚指定的配置项和数据显示图表。
      myChart.setOption(option);
    }
  }
};
